m=np.arange(1,13);f=np.array([2.95,2.85,2.75,2.70,2.80,2.90,3.05,3.20,3.45,3.75,4.05,4.20]);ax.plot(m,f,color=ACCENT,marker='o',lw=2);ax.fill_between(m,f,.0,color=ACCENT,alpha=.08);ax.axvspan(5.5,8.5,color=GOOD,alpha=.10);ax.text(6.0,4.35,'summer injection window',fontsize=7.5,color=GOOD);ax.set_xticks(m,['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']);ax.tick_params(axis='x',rotation=35);ax.set_ylabel('Forward price (USD/MMBtu)');ax.set_title('Illustrative Henry Hub seasonal curve',loc='left');ax.grid(alpha=.2)
